const BY_ID: ReadonlyMap<string, BrandAsset> = new Map(ASSETS.map((a) => [a.id, a]));

export function assetsFor(brand: BrandId): readonly BrandAsset[] {
  return ASSETS.filter((a) => a.brand === brand);
}

export function getAsset(id: string): BrandAsset | undefined {
  return BY_ID.get(id);
}

export function assetsByKind(kind: AssetKind, brand?: BrandId): readonly BrandAsset[] {
  return ASSETS.filter((a) => a.kind === kind && (brand === undefined || a.brand === brand));
}

